Item.method_code:
Innovator inn = this.getInnovator();

String docQuery = @"
<AML>
<Item type='Document' action='get'>
<file_item>" + this.getID() + @"</file_item>
</Item>
</AML>";
Item res = inn.applyAML(docQuery);

if (res.isError() || res.getItemCount()<1)
{
    return inn.newResult("0");
}

return inn.newResult("1");
